async function renderCompatPage(slug, env) {
  const parsed = parsePairSlug(slug);
  if (!parsed.ok || !parsed.first || !parsed.second) return { status: 404 };
  const { canonical, first, second } = canonicalPair(parsed.first, parsed.second);
  if (canonical !== slug.toLowerCase()) {
    return { status: 301, redirect: `/gab44/compatibility/${canonical}` };
  }
  try {
    const reading = await generateCompat(first, second, env);
    return { status: 200, html: compatPageHTML(reading) };
  } catch (err) {
    const placeholder = {
      pair: canonical,
      first,
      second,
      spark: "This pair note is being written. Check back in a moment \u2014 or request a personal reading below for one written by name, for you two.",
      friction: "",
      strength: "",
      move: "Request a $9 personal reading \u2014 written by hand, for one human (or one couple), within 48 hours.",
      source: "placeholder \xB7 " + String(err?.message ?? "").slice(0, 60),
      generated_at: (/* @__PURE__ */ new Date()).toISOString(),
      cached: false
    };
    return { status: 200, html: compatPageHTML(placeholder) };
  }
}
